#!/usr/bin/env bash
set -euo pipefail

# GTK colors are generated by matugen templates, not here:
#   templates/gtk.css                 -> ~/.config/gtk-4.0/gtk.css
#   templates/gtk3-{light,dark}.css   -> ~/.local/share/themes/RPRice/gtk-3.0/  (GTK3, Thunar)
#
# Matugen has already run by the time modules execute, so this module only drops
# the leftovers of the older pipeline. ~/.config/gtk-3.0/gtk.css has to go: the
# user stylesheet outranks the theme and never live-reloads, so leaving it around
# would freeze GTK3 apps on whatever colors they started with.

rm -f "$HOME/.config/gtk-3.0/colors.css" "$HOME/.config/gtk-3.0/gtk.css"
